/* ---------- Multi-select ---------- */
/* a combobox that keeps what you pick as chips: typing filters the list, the arrows move through it, Enter picks or
   unpicks, Escape closes it, and Backspace in an empty box takes the last chip off. As wide as the other single fields; the
   list opens from the box (placePop) and the box glides up with it, so the two sit centred together (centre()). The rows'
   checkboxes stand on the column the box's words start on, 12px in, and their counts end 12px in */
.msc{position:relative;width:100%;max-width:var(--dm-field-w);margin:0 auto;display:flex;flex-direction:column;gap:6px}
.msc-top{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:22px}
.msc-l{font-size:12.5px;font-weight:500}
.msc-clr{height:22px;padding:0 6px;margin-right:-6px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));font-size:12px;color:var(--dm-muted);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.msc-clr:hover{color:var(--dm-fg);background:var(--dm-row)}}
/* (its chips and its text box are all 26px tall: the lines they wrap onto are centred in the box) */
.msc-f{position:relative;display:flex;flex-wrap:wrap;align-items:flex-start;align-content:center;gap:6px;min-height:var(--dm-field-h);padding:6px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);cursor:text;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.msc-f{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* the edge steps up while its search box has the focus or its list is open; a tag's remove button rings on its own, never
   inside the field */
.msc-f:has(.msc-q:focus),.msc:has(.msc-pop.open) .msc-f{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.msc-q{flex:1;min-width:80px;height:26px;border:0;outline:0;background:transparent;padding:0 6px;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.msc-q::placeholder{color:var(--dm-muted)}
.msc-c{display:inline-flex;align-items:center;gap:2px;height:26px;padding:0 3px 0 var(--dm-s-2);border-radius:var(--dm-r-tag);background:var(--dm-chip);font-size:12.5px;white-space:nowrap}
@supports (corner-shape:squircle){.msc-c{corner-shape:squircle;border-radius:var(--dm-r-tag-sq)}}
.msc-c button{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;color:var(--dm-muted);transition:background .2s,color .2s}
@media (hover:hover) and (pointer:fine){.msc-c button:hover{background:color-mix(in srgb,currentColor 12%,transparent);color:var(--dm-fg)}}
.msc-c.go{animation:mscout .22s var(--dm-ease) forwards}
@keyframes mscout{to{opacity:0;transform:scale(.85)}}
/* the key just pressed, while the preview plays, at the end of the line the cursor is on */
.msc-key{position:absolute;right:8px;bottom:10px;opacity:0;transition:opacity .2s}
.msc-key.on{opacity:1}
.msc-pop{left:0;right:0;min-width:0}
/* (the rows are placed against the list itself, so keeping the highlighted one in view scrolls by the list's own measure) */
.msc-list{position:relative;max-height:210px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.msc-o{display:flex;align-items:center;gap:10px;min-height:34px;padding:6px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;cursor:pointer;flex:none;transition:background var(--dm-t-fast)}
.msc-o.hl{background:var(--dm-row)}
.msc-o .bx{width:16px;height:16px;border-radius:var(--dm-r-tiny,5px);box-shadow:inset 0 0 0 1.5px var(--dm-fg2);display:grid;place-items:center;color:transparent;flex:none;transition:background .2s,box-shadow .2s,color .2s}
.msc-o[aria-selected="true"] .bx{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent));color:var(--dm-on-accent)}
.msc-o .n{margin-left:auto;font-size:12px;color:var(--dm-muted);transition:color var(--dm-t-fast)}
/* on a highlighted row's grey the count steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
.msc-o.hl .n{color:var(--dm-fg2)}
.msc-none{padding:var(--dm-s-2) 6px;font-size:12.5px;color:var(--dm-muted)}
.msc-h{font-size:12px;transition:opacity var(--dm-t-fast) var(--dm-ease)}
/* the open list covers the hint under the box, so the hint steps aside instead of peeking out above the list */
.msc:has(.msc-pop.open) .msc-h{opacity:0}
/* Clean: the chips are tags with rounded corners, not pills; the list has the menus' 22px corners and its rows follow them;
   a checkbox is a rounded square with an inner shadow, ink once ticked (as Permission gate's) */
:root[data-style="clean"] .msc-c,:root [data-style="clean"] .msc-c,:root [data-style="clean"].msc-c{border-radius:var(--dm-r-sm)}
:root[data-style="clean"] .msc-pop,:root [data-style="clean"] .msc-pop,:root [data-style="clean"].msc-pop{border-radius:var(--dm-r-card)}
:root[data-style="clean"] .msc-o,:root [data-style="clean"] .msc-o,:root [data-style="clean"].msc-o{border-radius:calc(var(--dm-r-card) - 6px)}
:root[data-style="clean"] .msc-o .bx,:root [data-style="clean"] .msc-o .bx,:root [data-style="clean"].msc-o .bx{border-radius:calc(3px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-fg2),var(--dm-track-ring)}
:root[data-style="clean"] .msc-o[aria-selected="true"] .bx,:root [data-style="clean"] .msc-o[aria-selected="true"] .bx,:root [data-style="clean"].msc-o[aria-selected="true"] .bx{background:linear-gradient(180deg,var(--dm-btn-1),var(--dm-btn-2));box-shadow:inset 0 0 0 1px var(--dm-btn-2),inset 0 2px 3px -1px rgba(255,255,255,.28);color:var(--dm-on-btn)}

DM.def('multi-select', (r, c) => {
  const uid = Math.random().toString(36).slice(2, 7);
  // tags for the pricing page, and how many files carry each
  const T = [['Accessibility', 14], ['Billing', 9], ['Copy', 22], ['Design system', 31], ['Launch', 12], ['Mobile', 18], ['Onboarding', 7], ['Pricing', 16], ['Research', 11], ['Tokens', 25], ['Tooltips', 6]];
  const f = $('.msc-f', r), q = $('.msc-q', r), pop = $('.msc-pop', r), list = $('.msc-list', r), key = $('.msc-key', r), label = $('.msc-l', r);
  q.id = 'msc-q-' + uid; label.htmlFor = q.id; list.id = 'msc-l-' + uid; q.setAttribute('aria-controls', list.id);
  let picked = ['Launch'], hi = 0, opts = [];
  const clr = $('.msc-clr', r);
  // the chips sit in the box before the input, each with its own remove button
  function chips(){
    $$('.msc-c', f).forEach(ch => ch.remove());
    picked.forEach(t => { const ch = html(`<span class="msc-c" data-t="${t}">${t}<button aria-label="Remove ${t}">${I('x','xs')}</button></span>`); $('button', ch).onclick = e => { e.stopPropagation(); remove(t); }; f.insertBefore(ch, q); });
    clr.hidden = !picked.length;
    place();
  }
  // the list hangs 6px under the box, which grows as the chips wrap; opened over the box, it stands 6px over it
  let up = false;
  const place = () => { if (up){ pop.style.top = 'auto'; pop.style.bottom = (box.offsetHeight - f.offsetTop + 6) + 'px'; } else { pop.style.top = (f.offsetTop + f.offsetHeight + 6) + 'px'; pop.style.bottom = ''; } };
  function paint(){
    const v = q.value.trim().toLowerCase(), m = T.filter(([t]) => !v || t.toLowerCase().includes(v));
    list.innerHTML = m.length ? m.map(([t, n], i) => `<div class="msc-o" role="option" id="msc-o-${i}-${uid}" aria-selected="${picked.includes(t)}" data-t="${t}"><span class="bx">${I('check','xs')}</span>${t}<span class="n num">${n}</span></div>`).join('') : '<div class="msc-none">No tags match</div>';
    opts = $$('.msc-o', list); hi = Math.min(hi, Math.max(0, opts.length - 1)); move(0);
    opts.forEach((o, i) => { o.onmousemove = () => { if (hi !== i){ hi = i; move(0); } }; o.onmousedown = e => e.preventDefault(); o.onclick = () => toggle(o.dataset.t); });
  }
  function move(d){
    if (!opts.length){ q.removeAttribute('aria-activedescendant'); return; }
    hi = (hi + d + opts.length) % opts.length; opts.forEach((o, i) => o.classList.toggle('hl', i === hi));
    q.setAttribute('aria-activedescendant', opts[hi].id);
    const o = opts[hi], top = o.offsetTop, bot = top + o.offsetHeight;
    if (top < list.scrollTop) list.scrollTop = top; else if (bot > list.scrollTop + list.clientHeight) list.scrollTop = bot - list.clientHeight;
  }
  const isOpen = () => pop.classList.contains('open');
  // the box sits centred on its own, and glides up as the list opens, so the two sit centred together at every moment, as
  // typing narrows the list too. The list's place comes from the box, not its top mid-move, so chips wrapping onto a new
  // line move both together
  const box = $('.msc', r), full = () => pop.offsetHeight - list.offsetHeight + parseFloat(getComputedStyle(list).maxHeight);
  const centred = centre(c, box, () => isOpen() && !up ? Math.max(box.offsetHeight, f.offsetTop + f.offsetHeight + 6 + pop.offsetHeight) : box.offsetHeight, [pop]);
  // the list opens under the box; on a page of your own, over it when the window has no room under the box (placePop)
  function drop(){
    up = false; centred();
    const gy = parseFloat(box.style.getPropertyValue('--dm-gy')) || 0, now = new DOMMatrixReadOnly(getComputedStyle(box).transform).m42, dy = gy - now;
    const room = popRoom(f), b = f.getBoundingClientRect(), below = room.bottom - b.bottom - dy, above = b.top + dy - room.top;
    // (in a demo's stage the list always opens under the field, which glides up to make room for it)
    up = !r.closest('.stage-in') && below < full() + 12 && above > below; if (up) centred();
    f.dataset.popPos = up ? 'up' : 'down'; placePop(f, pop); place();
  }
  function open(){ if (isOpen()) return; pop.classList.add('open'); q.setAttribute('aria-expanded', 'true'); hi = 0; paint(); drop(); }
  // on closing, the box waits for the list to fade before it glides back to the middle
  function close(){ pop.classList.remove('open'); q.setAttribute('aria-expanded', 'false'); q.removeAttribute('aria-activedescendant'); c.later(REDUCE ? 0 : 180, centred); }
  // Enter or a click picks a tag, or unpicks one already picked; the box clears for the next one
  function toggle(t){ picked = picked.includes(t) ? picked.filter(x => x !== t) : [...picked, t]; q.value = ''; chips(); paint(); hi = Math.max(0, opts.findIndex(o => o.dataset.t === t)); move(0); }
  function remove(t){ const ch = $(`.msc-c[data-t="${t}"]`, f); picked = picked.filter(x => x !== t); if (ch && !REDUCE){ ch.classList.add('go'); c.later(220, () => { chips(); if (isOpen()) paint(); }); } else { chips(); if (isOpen()) paint(); } }
  // a click on the box opens the list; only a real click takes the focus, so the preview never moves the page
  f.onclick = e => { if (e.target.closest('.msc-c')) return; if (e.isTrusted) q.focus({ preventScroll:true }); open(); };
  q.oninput = () => { open(); hi = 0; paint(); };
  q.onkeydown = e => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); if (!isOpen()) return open(); move(e.key === 'ArrowDown' ? 1 : -1); }
    else if (e.key === 'Enter'){ e.preventDefault(); if (isOpen() && opts[hi]) toggle(opts[hi].dataset.t); else open(); }
    else if (e.key === 'Escape'){ if (isOpen()){ e.preventDefault(); close(); } }
    else if (e.key === 'Backspace' && !q.value && picked.length) remove(picked[picked.length - 1]);
    else if (e.key === 'Tab') close();
  };
  c.on(document, 'pointerdown', e => { if (!r.contains(e.target)) close(); });
  // Clear all takes every chip off at once; the cursor goes back to the box, so the next tag can be typed straight away
  clr.onmousedown = e => e.preventDefault();
  clr.onclick = e => { picked = []; chips(); if (isOpen()) paint(); if (e.isTrusted) q.focus({ preventScroll:true }); };
  chips();
  // the preview's story types and presses keys in the box without taking the focus, and shows each key as it goes
  const press = async (s, k, label) => { key.textContent = label || k; key.classList.add('on'); q.dispatchEvent(new KeyboardEvent('keydown', { key:k, bubbles:true })); await s.beat(2); key.classList.remove('on'); };
  const type = (s, text) => s.type(q, text, { n:.4, each:() => q.oninput(), keep:true });
  // the preview's story: add Pricing, pick Tooltips by mistake and take it off with Backspace, then add Tokens
  c.story(async s => {
    await s.beat(3);
    await s.tap(f); open(); s.away(); await s.beat(2);
    await type(s, 'pri'); await s.beat(1);
    await press(s, 'Enter');
    await type(s, 'to'); await s.beat(1);
    await press(s, 'ArrowDown', '↓');
    await press(s, 'Enter'); await s.beat(1);
    await press(s, 'Backspace');
    await type(s, 'tok'); await s.beat(1);
    await press(s, 'Enter');
    await press(s, 'Escape', 'Esc'); await s.beat(2);
  });
});
